deeper_reasoning_1:
\textbf{Claim.}
The construction-side core results jointly certify the goal-level vortex object. For every $N\ge2$ with $\gcd(N,p)=1$, $pq\equiv1\pmod N$, and $L_3\gg NL_4$, the asymmetric KvBLLY construction gives an object $V_{N,p,q}^{\rm asym}$ in the intended success set:
\[
\Phi_V=e^{2\pi iq/N},\qquad Q_{\rm top}(V)=\frac1N,\qquad S_{\rm YM}(V)=\frac{8\pi^2}{Ng^2}.
\]

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,\quad \gcd(N,p)=1,\quad pq\equiv1\pmod N,\quad L_3\gg NL_4.\\
\text{(P2)}\quad &P_3=S^{-p},\quad P_4=C^{-1},\quad
\operatorname{tr}(P_3^{n_3}P_4^{n_4})=0
\text{ unless }n_3\equiv n_4\equiv0\pmod N.\\
\text{(P3)}\quad &m^2_{Nk_3+\ell_3,Nk_4+\ell_4}
=\left(\frac{2\pi}{N}\right)^2
\left(\frac{(Nk_3+\ell_3)^2}{L_3^2}
+\frac{(Nk_4+\ell_4)^2}{L_4^2}\right)>0
\text{ for }(\ell_3,\ell_4)\neq(0,0).\\
\text{(P4)}\quad &\vec\alpha_n=\vec w_n^{(q)}-P_W^p\vec w_n^{(q)},\qquad
\vec w_n^{(q)}=\sum_{a=0}^{q-1}\vec\nu_{n+ap}.\\
\text{(P5)}\quad &\vec\varphi_\infty=\vec\varphi_c,\qquad
\vec\sigma,\ \vec\varphi-\vec\varphi_c=O(e^{-2\pi |x|/(NL_3)}).\\
\text{(P6)}\quad &\int_C\vec a=-2\pi\vec w_n^{(q)}
\Longrightarrow W(C)\mapsto e^{2\pi iq/N}W(C).\\
\text{(P7)}\quad &\text{The minimal center vortex is self-dual and has }
Q_{\rm top}=1/N,\quad S_{\rm YM}=8\pi^2/(Ng^2).
\end{align*}

\textbf{Derivation.}
\begin{align}
\text{(P2)}
&\Longrightarrow \text{the classical twisted vacuum preserves the two compact center symmetries}
&&\text{all nontrivial traced holonomies vanish}.
\end{align}
\begin{align}
\text{(P3)}
&\Longrightarrow \text{there is no unwanted massless two-dimensional fluctuation}
&&\text{all nonzero twist sectors are gapped}.
\end{align}
\begin{align}
\text{(P4)}
&\Longrightarrow \text{the monopole root is exactly the mismatch between adjacent }p\text{-Weyl-related fluxes}
&&\text{root--weight decomposition}.
\end{align}
Together with the center-twisted boundary condition in the asymmetric regime, this mismatch identifies the emitted and absorbed fluxes after one $x_3$ period, so it produces a codimension-two flux tube rather than an unclosed monopole flux line. By (P5), the fields approach the center-symmetric holonomy exponentially, hence the tube is localized in the $\mathbb R^2$ directions. By (P6),
\begin{align}
\Phi_V&=e^{2\pi iq/N}.
\end{align}
By (P7),
\begin{align}
Q_{\rm top}(V)&=\frac1N,\\
S_{\rm YM}(V)&=\frac{8\pi^2}{Ng^2}.
\end{align}
Therefore the constructed object satisfies every construction-side predicate: coprime non-minimal twist, center-symmetric background, perturbative gap, localized center flux, fundamental Wilson phase, fractional charge, and self-dual action.

\textbf{Final Result.}
\[
\boxed{
V_{N,p,q}^{\rm asym}\in\Sigma_V,\qquad
\Phi_V=e^{2\pi iq/N},\quad
Q_{\rm top}=\frac1N,\quad
S_{\rm YM}=\frac{8\pi^2}{Ng^2}
}
\]
\hfill$\blacksquare$

deeper_reasoning_2:
\textbf{Claim.}
The identity
\[
\vec\alpha_j=\vec w_j^{(q)}-P_W^p\vec w_j^{(q)}
\]
is a flux-closure certificate: it makes the flux emitted below a monopole and the flux absorbed above it differ by exactly the $p$-fold Weyl twist, so the periodic chain of monopole images forms a closed center-vortex tube.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,\quad \gcd(N,p)=1,\quad pq\equiv1\pmod N.\\
\text{(P2)}\quad &P_W^p\vec\nu_j=\vec\nu_{j+p},\qquad
P_W^p\vec w_j^{(q)}=\vec w_{j+p}^{(q)}.\\
\text{(P3)}\quad &\vec\alpha_j=\vec w_j^{(q)}-\vec w_{j+p}^{(q)}.\\
\text{(P4)}\quad &\vec F_j:=-2\pi\vec w_j^{(q)}\text{ is the center-vortex flux assigned to the interval labelled }j.\\
\text{(P5)}\quad &\vec z(x,x_3)=P_W^{-p}\vec z(x,x_3+L_3).\\
\text{(P6)}\quad &\text{Labels in the image chain are }j=n+kp\pmod N,\quad k\in\mathbb Z.\\
\text{(P7)}\quad &\gcd(N,p)=1\text{ implies }n,n+p,\ldots,n+(N-1)p\text{ exhaust all labels modulo }N.
\end{align*}

\textbf{Derivation.}
For adjacent intervals in the image chain,
\begin{align}
\vec F_j-\vec F_{j+p}
&=-2\pi\vec w_j^{(q)}+2\pi\vec w_{j+p}^{(q)}
&&\text{by (P4)}\\
&=-2\pi\left(\vec w_j^{(q)}-\vec w_{j+p}^{(q)}\right)
&&\text{factor }-2\pi\\
&=-2\pi\vec\alpha_j
&&\text{by (P3)}.
\end{align}
Thus the monopole root accounts for the full discontinuity between the two neighboring flux assignments. Applying the boundary twist,
\begin{align}
P_W^{-p}\vec F_{j+p}
&=P_W^{-p}\left(-2\pi\vec w_{j+p}^{(q)}\right)
&&\text{by (P4)}\\
&=-2\pi\vec w_j^{(q)}
&&\text{by (P2)}\\
&=\vec F_j
&&\text{by (P4)}.
\end{align}
Hence the flux above the monopole, after transport through one twisted $x_3$ period, is identified with the flux below the monopole. Finally, after $N$ steps,
\begin{align}
j+Np&\equiv j\pmod N
&&\text{because }Np\equiv0\pmod N,\\
\vec F_{j+Np}&=\vec F_j
&&\text{labels are modulo }N.
\end{align}
By (P7), this single chain passes through every Weyl label before closing. Therefore no extra endpoint flux remains: the monopole-source discontinuities glue into one closed center-vortex tube.

\textbf{Final Result.}
\[
\boxed{
\vec F_j-\vec F_{j+p}=-2\pi\vec\alpha_j,\qquad
P_W^{-p}\vec F_{j+p}=\vec F_j,\qquad
\vec F_{j+Np}=\vec F_j
}
\]
\hfill$\blacksquare$

deeper_reasoning_3:
\textbf{Claim.}
The constrained dilute gas does more than give a formal partition function: it gives an $N$-branch vacuum system in which the full theory is $2\pi$-periodic in $\theta$, each branch is $2\pi N$-periodic, and neighboring dominant branches cross with a cusp at odd multiples of $\pi$.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &a:=K e^{-8\pi^2/(Ng^2)}>0.\\
\text{(P2)}\quad &E_k(\theta):=-2a\cos\left(\frac{\theta-2\pi k}{N}\right),
\qquad k\in\mathbb Z/N\mathbb Z.\\
\text{(P3)}\quad &Z_{\rm eff,\theta}:=\sum_{k=0}^{N-1}e^{-VE_k(\theta)}.\\
\text{(P4)}\quad &E_{\rm vac}(\theta):=\min_{k\in\mathbb Z/N\mathbb Z}E_k(\theta).\\
\text{(P5)}\quad &\frac{dE_k}{d\theta}=\frac{2a}{N}\sin\left(\frac{\theta-2\pi k}{N}\right).\\
\text{(P6)}\quad &\cos x\text{ is maximal, hence }E_k(\theta)\text{ is minimal, when }
|\theta-2\pi k|\text{ is smallest modulo }2\pi N.
\end{align*}

\textbf{Derivation.}
First, shift $\theta$ by $2\pi$:
\begin{align}
Z_{\rm eff,\theta+2\pi}
&=\sum_{k=0}^{N-1}\exp\left[-V E_k(\theta+2\pi)\right]
&&\text{by (P3)}\\
&=\sum_{k=0}^{N-1}
\exp\left[2Va\cos\left(\frac{\theta-2\pi(k-1)}{N}\right)\right]
&&\text{by (P2)}\\
&=\sum_{j=0}^{N-1}
\exp\left[2Va\cos\left(\frac{\theta-2\pi j}{N}\right)\right]
&&\text{set }j=k-1\pmod N\\
&=Z_{\rm eff,\theta}
&&\text{by (P3)}.
\end{align}
Second, for a fixed branch,
\begin{align}
E_k(\theta+2\pi N)
&=-2a\cos\left(\frac{\theta+2\pi N-2\pi k}{N}\right)
&&\text{by (P2)}\\
&=-2a\cos\left(\frac{\theta-2\pi k}{N}+2\pi\right)
&&\text{algebra}\\
&=E_k(\theta)
&&\text{periodicity of }\cos .
\end{align}
At $\theta=(2j+1)\pi$,
\begin{align}
E_j((2j+1)\pi)
&=-2a\cos\left(\frac{\pi}{N}\right),\\
E_{j+1}((2j+1)\pi)
&=-2a\cos\left(-\frac{\pi}{N}\right)
=-2a\cos\left(\frac{\pi}{N}\right),
\end{align}
so the two neighboring branches are degenerate. Their slopes are
\begin{align}
E_j'((2j+1)\pi)
&=\frac{2a}{N}\sin\left(\frac{\pi}{N}\right),\\
E_{j+1}'((2j+1)\pi)
&=\frac{2a}{N}\sin\left(-\frac{\pi}{N}\right)
=-\frac{2a}{N}\sin\left(\frac{\pi}{N}\right).
\end{align}
Thus the dominant branch changes there with unequal one-sided derivatives.

\textbf{Final Result.}
\[
\boxed{
Z_{\rm eff,\theta+2\pi}=Z_{\rm eff,\theta},\qquad
E_k(\theta+2\pi N)=E_k(\theta),\qquad
E_{\rm vac}(\theta)\text{ has cusps at }\theta=(2j+1)\pi
}
\]
\hfill$\blacksquare$

deeper_reasoning_5:
\textbf{Claim.}
The background-field extension gives one unified consistency certificate: the reduced two-dimensional invariant is the four-dimensional cup-square anomaly invariant, the same invariant controls the $k$-branch response and the $\theta\mapsto\theta+2\pi$ anomaly, and in the special $A_3=A_4=0$ sector it enforces the shifted vortex-number congruence that cancels fractional magnetic flux.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &J:=\int \frac12 B_{4d}\cup B_{4d}.\\
\text{(P2)}\quad &\text{Under reduction on }M_2\times T^2\text{ with }3\text{-}4\text{ twist }p,\\
&J\equiv \int_{M_2}(B_{2d}\cup B_{34}-A_3\cup A_4)\pmod N,
\qquad B_{34}=p.\\
\text{(P3)}\quad &I:=\int_{M_2}(pB_{2d}-A_3\cup A_4).\\
\text{(P4)}\quad &a:=K e^{-8\pi^2/(Ng^2)}.\\
\text{(P5)}\quad &Z_{\theta,k}[B_{2d},A_3,A_4]
:=e^{-2\pi ikI/N}
\exp\left[2Va\cos\left(\frac{\theta-2\pi k}{N}\right)\right].\\
\text{(P6)}\quad &Z_{\rm eff,\theta}[B_{2d},A_3,A_4]
:=\sum_{k=0}^{N-1}Z_{\theta,k}[B_{2d},A_3,A_4].\\
\text{(P7)}\quad &\sum_{k=0}^{N-1}e^{-2\pi ikr/N}\neq0\Longleftrightarrow r\equiv0\pmod N.\\
\text{(P8)}\quad &A_3=A_4=0,
\quad m:=\int_{M_2}B_{2d}
\Longrightarrow I=pm.\\
\text{(P9)}\quad &Q_{\rm top}=(n-\bar n)/N,
\qquad pq\equiv1\pmod N.
\end{align*}

\textbf{Derivation.}
First reduce the four-dimensional anomaly invariant:
\begin{align}
J
&\equiv \int_{M_2}(B_{2d}\cup B_{34}-A_3\cup A_4)
&&\text{by (P2)}\\
&=\int_{M_2}(pB_{2d}-A_3\cup A_4)
&&\text{because }B_{34}=p\\
&=I
&&\text{by (P3)}.
\end{align}
Thus the branch factor in (P5) can be written with the four-dimensional invariant:
\begin{align}
Z_{\theta,k}[B_{2d},A_3,A_4]
&=e^{-2\pi ikI/N}Z_{\theta,k}[0,0,0]
&&\text{by (P5)}\\
&=e^{-2\pi ikJ/N}Z_{\theta,k}[0,0,0]
&&\text{since }I\equiv J\pmod N.
\end{align}
For the full partition function under $\theta\mapsto\theta+2\pi$,
\begin{align}
Z_{\rm eff,\theta+2\pi}[B_{2d},A_3,A_4]
&=\sum_{k=0}^{N-1}e^{-2\pi ikI/N}
\exp\left[2Va\cos\left(\frac{\theta+2\pi-2\pi k}{N}\right)\right]\\
&=\sum_{j=0}^{N-1}e^{-2\pi i(j+1)I/N}
\exp\left[2Va\cos\left(\frac{\theta-2\pi j}{N}\right)\right]
&&\text{set }j=k-1\pmod N\\
&=e^{-2\pi iI/N}Z_{\rm eff,\theta}[B_{2d},A_3,A_4]\\
&=e^{-2\pi iJ/N}Z_{\rm eff,\theta}[B_{2d},A_3,A_4].
\end{align}
This proves the anomaly and branch-response parts.

Now set $A_3=A_4=0$.  In the vortex-number expansion, the finite Fourier projector has argument $n-\bar n+I=n-\bar n+pm$.  Hence
\begin{align}
\sum_{k=0}^{N-1}e^{-2\pi ik(n-\bar n+pm)/N}\neq0
&\Longleftrightarrow n-\bar n+pm\equiv0\pmod N
&&\text{by (P7)}\\
&\Longleftrightarrow n-\bar n\equiv-pm\pmod N.
\end{align}
Therefore $n-\bar n=-pm+Ns$ for some $s\in\mathbb Z$, and
\begin{align}
Q_{\rm top}
&=\frac{n-\bar n}{N}
&&\text{by (P9)}\\
&=-\frac{pm}{N}+s
\in-\frac{pm}{N}+\mathbb Z.
\end{align}
The total fractional magnetic flux cancels because
\begin{align}
\frac{q}{N}(n-\bar n)+\frac{m}{N}
&\equiv -\frac{qpm}{N}+\frac{m}{N}\\
&=\frac{m(1-pq)}{N}\\
&\equiv0\pmod1
&&\text{by }pq\equiv1\pmod N.
\end{align}

\textbf{Final Result.}
\[
\boxed{
J\equiv I\pmod N,
\qquad
Z_{\rm eff,\theta+2\pi}[B]=e^{-2\pi iJ/N}Z_{\rm eff,\theta}[B],
\qquad
Z_{\theta,k}[B]=e^{-2\pi ikJ/N}Z_{\theta,k}[0]
}
\]
\[
\boxed{
n-\bar n\equiv-pm\pmod N,
\qquad
Q_{\rm top}\in-\frac{pm}{N}+\mathbb Z,
\qquad
\frac{q}{N}(n-\bar n)+\frac{m}{N}=0\pmod1
}
\]
\hfill$\blacksquare$

deeper_reasoning_6:
\textbf{Claim.}
Large-$N$ center stabilization requires simultaneous residue control of fixed multiples of $q_N$ and $p_N$. Fixed multiples of $q_N$ control light Wilson-loop tensions, while fixed multiples of $p_N$ control the one-site singular-toron action-versus-entropy instability.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\to\infty,\qquad \gcd(N,p_N)=1,\qquad p_Nq_N\equiv1\pmod N.\\
\text{(P2)}\quad &d_N(x):=\min_{s\in\mathbb Z}|x-sN|.\\
\text{(P3)}\quad &T_m=\sigma\sin^2\left(\frac{\pi q_Nm}{N}\right)
=\sigma\sin^2\left(\frac{\pi d_N(q_Nm)}{N}\right),
\quad \sigma>0,\quad m\text{ fixed}.\\
\text{(P4)}\quad &V_{\rm cl}^{\rm toron}(m)=\frac{4N^2}{\lambda}
\sin^2\left(\frac{\pi m p_N}{N}\right)
=\frac{4N^2}{\lambda}
\sin^2\left(\frac{\pi d_N(mp_N)}{N}\right).\\
\text{(P5)}\quad &V_{\rm eff}^{\rm toron}=V_{\rm cl}^{\rm toron}-cN^2,\qquad c>0,\quad c=O(1).\\
\text{(P6)}\quad &\sin x=x+O(x^3)\text{ as }x\to0.\\
\text{(P7)}\quad &\text{Large-}N\text{ stability demands nonzero limiting tensions for fixed nonzero }m
\text{ and no }O(N^{-2})\text{ weak-coupling toron threshold.}
\end{align*}

\textbf{Derivation.}
If for some fixed $m\neq0$,
\begin{align}
d_N(q_Nm)&=O(1),
\end{align}
then by (P3) and (P6),
\begin{align}
T_m
&=\sigma\left(\frac{\pi d_N(q_Nm)}{N}+O(N^{-3})\right)^2\\
&=O(N^{-2}).
\end{align}
Thus the fixed light charge loses its limiting string tension. Therefore avoiding this one-form failure requires
\begin{align}
d_N(q_Nm)&\text{ to be of order }N
\quad\text{for every fixed }m\neq0.
\end{align}
If instead for some fixed $m\neq0$,
\begin{align}
d_N(mp_N)&=O(1),
\end{align}
then by (P4) and (P6),
\begin{align}
V_{\rm cl}^{\rm toron}(m)
&=\frac{4N^2}{\lambda}
\left(\frac{\pi d_N(mp_N)}{N}+O(N^{-3})\right)^2\\
&=O(\lambda^{-1}).
\end{align}
Using (P5), the estimated transition solves
\begin{align}
0&=O(\lambda_*^{-1})-cN^2,\\
\lambda_*&=O(N^{-2}).
\end{align}
This is the same destabilizing scaling as fixed twist. Therefore avoiding this zero-form failure requires
\begin{align}
d_N(mp_N)&\text{ to be of order }N
\quad\text{for every fixed }m\neq0.
\end{align}

\textbf{Final Result.}
\[
\boxed{
\forall m\in\mathbb Z_{>0}\text{ fixed}:\quad
d_N(q_Nm)\asymp N
\quad\text{and}\quad
d_N(p_Nm)\asymp N
}
\]
is the simultaneous large-$N$ center-stability test extracted from the one-form and zero-form diagnostics.
\hfill$\blacksquare$

deeper_reasoning_7:
\textbf{Claim.}
The Fibonacci sequence
\[
N=F_{n+2},\qquad p=F_n,\qquad q=(-1)^nF_n
\]
passes the simultaneous large-$N$ stability test: $q$ is a modular inverse of $p$, every fixed nonzero multiple of $p$ and $q$ has residue of order $N$, and every fixed nonzero light charge has a nonzero limiting string tension.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &F_0=0,\quad F_1=1,\quad F_{n+2}=F_{n+1}+F_n.\\
\text{(P2)}\quad &N:=F_{n+2},\quad p:=F_n,\quad q:=(-1)^nF_n.\\
\text{(P3)}\quad &F_{n+1}^2-F_nF_{n+2}=(-1)^n,\qquad F_{n+1}=F_{n+2}-F_n.\\
\text{(P4)}\quad &\phi:=\frac{1+\sqrt5}{2},\quad
\phi^2=\phi+1,\quad
\frac{F_n}{F_{n+2}}\to\frac1{\phi^2}=2-\phi.\\
\text{(P5)}\quad &\phi\notin\mathbb Q.\\
\text{(P6)}\quad &d_N(x):=\min_{s\in\mathbb Z}|x-sN|.\\
\text{(P7)}\quad &T_m=\sigma\sin^2\left(\frac{\pi qm}{N}\right),\qquad
\sigma>0,\quad m\in\mathbb Z_{>0}\text{ fixed}.
\end{align*}

\textbf{Derivation.}
First,
\begin{align}
F_{n+1}^2-F_nF_{n+2}
&=(-1)^n
&&\text{by (P3)}\\
(F_{n+2}-F_n)^2-F_nF_{n+2}
&=(-1)^n
&&\text{by (P3)}\\
F_n^2&\equiv(-1)^n\pmod{F_{n+2}}
&&\text{reduce modulo }F_{n+2}.
\end{align}
Hence
\begin{align}
pq
&=F_n((-1)^nF_n)
&&\text{by (P2)}\\
&\equiv1\pmod{F_{n+2}}
&&\text{by the preceding congruence}\\
&\equiv1\pmod N.
\end{align}
For fixed $m\neq0$,
\begin{align}
\frac{mp}{N}
&=m\frac{F_n}{F_{n+2}}
\longrightarrow m(2-\phi).
\end{align}
Since $2-\phi$ is irrational, $m(2-\phi)\notin\mathbb Z$. Therefore
\begin{align}
\frac{d_N(mp)}{N}
&\longrightarrow
\min_{s\in\mathbb Z}|m(2-\phi)-s|>0.
\end{align}
Because $q=\pm p$, the same argument gives
\begin{align}
\frac{d_N(mq)}{N}
&\longrightarrow
\min_{s\in\mathbb Z}|m(2-\phi)-s|>0.
\end{align}
Finally,
\begin{align}
\lim_{n\to\infty}T_m
&=\sigma\sin^2\left(\pi m\lim_{n\to\infty}\frac{|q|}{N}\right)
&&\text{by (P7)}\\
&=\sigma\sin^2(\pi m(2-\phi))\\
&=\sigma\sin^2(\pi\phi m)
&&\text{periodicity of }\sin^2.
\end{align}
If this limit vanished, then $\phi m\in\mathbb Z$, implying $\phi\in\mathbb Q$, contradicting (P5). Hence the limit is positive.

\textbf{Final Result.}
\[
\boxed{
pq\equiv1\pmod N,\qquad
d_N(mp)\asymp N,\qquad d_N(mq)\asymp N,\qquad
T_m\to\sigma\sin^2(\pi\phi m)>0
}
\]
for every fixed $m\in\mathbb Z_{>0}$.
\hfill$\blacksquare$

deeper_reasoning_8:
\textbf{Claim.}
The continued-fraction diagnostic should be read as a finite-window refinement of the exact fixed-charge large-$N$ criterion.  If the limiting ratios of $q_N/N$ and $p_N/N$ are irrational, every fixed multiple has an $O(N)$ residue; continued fractions then identify which irrational limits are vulnerable to accidentally small tensions inside a growing but still low-charge window.  The Fibonacci limit passes the exact fixed-charge test and avoids large-partial-quotient accidents.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &\frac{q_N}{N}\to\xi_q,
\qquad
\frac{p_N}{N}\to\xi_p.\\
\text{(P2)}\quad &\xi_q\notin\mathbb Q,
\qquad
\xi_p\notin\mathbb Q.\\
\text{(P3)}\quad &\|x\|_{\mathbb Z}:=\min_{s\in\mathbb Z}|x-s|,
\qquad
\|y\|_N:=\min_{s\in\mathbb Z}|y-sN|.\\
\text{(P4)}\quad &T_m\to\sigma\sin^2(\pi m\xi_q),
\qquad \sigma>0,
\qquad m\in\mathbb Z_{>0}\text{ fixed}.\\
\text{(P5)}\quad &\frac{c_k}{d_k}\text{ is a continued-fraction convergent of }\xi_q,
\quad
\left|\xi_q-\frac{c_k}{d_k}\right|<\frac{1}{a_{k+1}d_k^2}.\\
\text{(P6)}\quad &|\sin x|\le |x|,
\qquad \sin^2(x+\pi s)=\sin^2x\text{ for }s\in\mathbb Z.\\
\text{(P7)}\quad &\xi_{\rm Fib}:=\frac1{\phi^2}=2-\phi,
\quad \phi:=\frac{1+\sqrt5}{2},
\quad \xi_{\rm Fib}=[0;2,1,1,1,\ldots].
\end{align*}

\textbf{Derivation.}
Fix $m\ge1$.  Since $\xi_q$ is irrational,
\begin{align}
\delta_{q,m}:=\|m\xi_q\|_{\mathbb Z}>0.
\end{align}
By convergence in (P1),
\begin{align}
\frac{\|mq_N\|_N}{N}
&=\left\|m\frac{q_N}{N}\right\|_{\mathbb Z}
\longrightarrow \|m\xi_q\|_{\mathbb Z}
=\delta_{q,m}>0.
\end{align}
Hence $\|mq_N\|_N=\Theta(N)$ for every fixed $m$.  The same argument using $\xi_p$ gives
\begin{align}
\frac{\|mp_N\|_N}{N}
&\longrightarrow \|m\xi_p\|_{\mathbb Z}>0,\qquad
\|mp_N\|_N=\Theta(N).
\end{align}
Thus irrational limiting ratios imply the exact pointwise fixed-charge residue condition.
The string tension is also nonzero:
\begin{align}
\lim_{N\to\infty}T_m
&=\sigma\sin^2(\pi m\xi_q)
&&\text{by (P4)}\\
&>0
&&\text{because }m\xi_q\notin\mathbb Z.
\end{align}
For a finite window $1\le m\le M$, define
\begin{align}
\Delta_M(\xi_q):=\min_{1\le m\le M}\|m\xi_q\|_{\mathbb Z}.
\end{align}
If $\xi_q$ is irrational, then $\Delta_M(\xi_q)>0$ for each fixed $M$; therefore all charges in that finite window have a common positive limiting tension lower bound
\begin{align}
\min_{1\le m\le M}\lim_{N\to\infty}T_m
&\ge \sigma\sin^2(\pi\Delta_M(\xi_q)).
\end{align}
Continued fractions diagnose when this finite-window lower bound can become poor as $M$ is enlarged.  Using (P5), write
\begin{align}
\xi_q=\frac{c_k}{d_k}+\varepsilon_k,
\qquad
|\varepsilon_k|<\frac{1}{a_{k+1}d_k^2}.
\end{align}
For the charge $m=d_k$,
\begin{align}
\sigma\sin^2(\pi d_k\xi_q)
&=\sigma\sin^2(\pi(c_k+d_k\varepsilon_k))\\
&=\sigma\sin^2(\pi d_k\varepsilon_k)\\
&\le \sigma\pi^2d_k^2\varepsilon_k^2\\
&<\sigma\left(\frac{\pi}{a_{k+1}d_k}\right)^2.
\end{align}
Thus a large partial quotient $a_{k+1}$ creates an accidentally small tension at the low charge $d_k$ relative to that approximation scale.  For the Fibonacci limit, (P7) gives no large partial quotients: after the initial $2$, all partial quotients are $1$.  It therefore passes the exact fixed-$m$ irrationality test and avoids this particular finite-window accident mechanism.

